// PrepareTranscript implements agent.TranscriptPreparer.
// It calls `opencode export` to refresh the transcript file before reading.
// The sessionRef is the path to the transcript file (e.g., .entire/tmp/<sessionID>.json).
func (a *OpenCodeAgent) PrepareTranscript(sessionRef string) error {
	// Extract session ID from the path: .entire/tmp/<sessionID>.json
	base := filepath.Base(sessionRef)
	sessionID := base[:len(base)-len(filepath.Ext(base))] // Remove .json extension

	_, err := a.fetchAndCacheExport(sessionID)
	return err
}

