// extractSessionDataFromLiveTranscript extracts session data directly from the live transcript file.
// This is used for mid-session commits where no shadow branch exists yet.
func (s *ManualCommitStrategy) extractSessionDataFromLiveTranscript(state *SessionState) (*ExtractedSessionData, error) {
	data := &ExtractedSessionData{}

	// Read the live transcript
	if state.TranscriptPath == "" {
		return nil, errors.New("no transcript path in session state")
	}

	// If the agent implements TranscriptPreparer, call PrepareTranscript to ensure
	// the transcript file is up-to-date. This is needed for OpenCode which exports
	// the transcript on-demand rather than writing it continuously.
	if state.AgentType != "" {
		if ag, err := agent.GetByAgentType(state.AgentType); err == nil {
			if preparer, ok := ag.(agent.TranscriptPreparer); ok {
				if err := preparer.PrepareTranscript(state.TranscriptPath); err != nil {
					// Log but continue - the file might already exist from a previous export
					logging.Debug(context.Background(), "failed to prepare transcript",
						"error", err, "path", state.TranscriptPath)
				}
			}
		}
	}

	liveData, err := os.ReadFile(state.TranscriptPath)
